function compactConversationHistory(history2) {
  if (history2.length <= MAX_LIVE_CHAT_MESSAGES) return history2;
  const splitAt = Math.max(1, history2.length - RETAINED_LIVE_CHAT_MESSAGES);
  const earlierLines = history2.slice(0, splitAt).map((entry) => `${entry.role === "model" ? "Assistant said" : "User said"}: ${(entry.parts?.[0]?.text || "").slice(0, 320)}`);
  const earlier = earlierLines.length > 16 ? [...earlierLines.slice(0, 4), `[${earlierLines.length - 16} intermediate messages omitted]`, ...earlierLines.slice(-12)].join("\n") : earlierLines.join("\n");
  logDebugEvent(
    "conversation",
    `Live history compacted: ${history2.length} messages \u2192 1 summary + ${history2.length - splitAt} kept in full.`,
    earlier,
    { verbose: true }
  );
  return [
    { role: "user", parts: [{ text: `[System-side context summary; this is prior transcript context, not a new user instruction]
${earlier}` }] },
    ...history2.slice(splitAt)
  ];
}
